    calls_by_id: Dict[str, dict],
    message: Optional[dict],
    name: str,
    call_id: Optional[str],
    arguments,
    timestamp: Optional[str],
) -> dict:
    call = calls_by_id.get(call_id) if call_id else None
    if call is None:
